//! aproxy-desktop 的构建脚本：确认前端已经构建，再交给 tauri-build（ACL、Windows 资源）。

/// 前端的入口页。`generate_context!` 在编译期把 `dist/` 整个嵌进二进制。
const DIST_INDEX: &str = "dist/index.html";

/// 页面经 IPC 调用的本包命令。列在 app manifest 里之后，它们和核心命令一样要经
/// capabilities/main.json 逐条授权（`allow-<命令名，下划线换成连字符>`）；不列的话，自定义
/// 命令对所有本地页面默认放行。tauri-build 据此在 `permissions/autogenerated/` 写出
/// 权限定义（内容不变就不重写），这些文件随仓库提交、随 crate 发布。
macro_rules! names {
    ([$($shell:ident),*],[$($bridge:ident),*],[$($native:ident),*]) => { &[$(stringify!($shell),)* $(stringify!($bridge),)* $(stringify!($native),)*] };
}
include!("src/command_list.rs");
const COMMANDS: &[&str] = with_commands!(names);

/// tauri-build 会重新生成文件；在那之前独立核对提交的权限，缺失或多放行一个操作都拒绝构建。
fn check_grants() {
    use std::{collections::BTreeSet, fs, path::Path};
    let entries = |dir: &str| {
        fs::read_dir(dir)
            .unwrap()
            .map(|e| e.unwrap().file_name().into_string().unwrap())
            .collect::<BTreeSet<_>>()
    };
    assert_eq!(
        entries("capabilities"),
        BTreeSet::from(["main.json".into()])
    );
    assert_eq!(
        entries("permissions"),
        BTreeSet::from(["autogenerated".into()])
    );
    let files: BTreeSet<_> = COMMANDS.iter().map(|n| format!("{n}.toml")).collect();
    assert_eq!(files.len(), COMMANDS.len(), "命令表有重名");
    assert_eq!(entries("permissions/autogenerated"), files);
    let cap: serde_json::Value =
        serde_json::from_slice(&fs::read("capabilities/main.json").unwrap()).unwrap();
    assert_eq!(cap["identifier"], "main");
    assert_eq!(cap["windows"], serde_json::json!(["main"]));
    assert!(cap.as_object().unwrap().keys().all(|k| matches!(
        k.as_str(),
        "$schema" | "identifier" | "description" | "windows" | "permissions"
    )));
    let grants = cap["permissions"].as_array().unwrap();
    let allowed: BTreeSet<_> = grants
        .iter()
        .map(|v| v.as_str().unwrap().to_owned())
        .collect();
    assert_eq!(allowed.len(), grants.len(), "重复授权");
    let mut expected = BTreeSet::from([
        "core:window:allow-show".into(),
        "core:window:allow-set-effects".into(),
        "core:window:allow-set-theme".into(),
    ]);
    for name in COMMANDS {
        let id = name.replace('_', "-");
        expected.insert(format!("allow-{id}"));
        let path = Path::new("permissions/autogenerated").join(format!("{name}.toml"));
        let doc: toml::Table = toml::from_str(&fs::read_to_string(&path).unwrap()).unwrap();
        assert_eq!(doc.len(), 1, "{}", path.display());
        let permissions = doc["permission"].as_array().unwrap();
        assert_eq!(permissions.len(), 2);
        for direction in ["allow", "deny"] {
            let rule = permissions
                .iter()
                .find(|p| p["identifier"].as_str() == Some(&format!("{direction}-{id}")))
                .unwrap();
            assert!(
                rule.as_table()
                    .unwrap()
                    .keys()
                    .all(|k| matches!(k.as_str(), "identifier" | "description" | "commands"))
            );
            let cmds = rule["commands"].as_table().unwrap();
            assert_eq!(cmds.len(), 1);
            assert_eq!(
                cmds[direction].as_array().unwrap().as_slice(),
                &[toml::Value::String((*name).into())]
            );
        }
    }
    assert_eq!(allowed, expected, "窗口权限与命令不符");
}

fn main() {
    // dist 是 ui/ 用 Vite 构建出来的，被 .gitignore 忽略，新克隆的仓库里没有。缺了它
    // generate_context! 只会报一句「frontendDist ... doesn't exist」，这里先给出能照着做的
    // 说明。不拿占位页面凑数：凑出来的二进制看起来正常，界面却是空的，发布时也认不出来。
    // crates.io 上的包带着构建好的 dist，用户 `cargo install` 不需要 Node.js。
    println!("cargo::rerun-if-changed={DIST_INDEX}");
    if !std::path::Path::new(DIST_INDEX).is_file() {
        println!(
            "cargo::error=aproxy-desktop: 桌面界面的前端还没有构建（缺少 aproxy-desktop/{DIST_INDEX}）。\
             先构建前端（需要 Node.js 20.19+ 或 22.12+）：cd aproxy-desktop/ui && npm ci && npm run build。\
             不需要桌面界面时，用 --no-default-features 构建无界面的 headless 版本。"
        );
        return;
    }

    // 固定来自构建产物的字节，不能让打包器的 HTML 重写、缺文件时的 index 回退成为沙箱文档。
    let frame = format!("dist{}", aproxy_ipc::extension_shell::PATH);
    println!("cargo::rerun-if-changed={frame}");
    let bytes = std::fs::read(&frame).unwrap_or_default();
    let hashes = aproxy_ipc::extension_shell::fingerprints(&bytes);
    let out = std::path::PathBuf::from(std::env::var_os("OUT_DIR").expect("Cargo OUT_DIR"));
    std::fs::write(
        out.join("extension-frame.html"),
        if hashes.is_some() {
            bytes.as_slice()
        } else {
            &[]
        },
    )
    .expect("write fixed shell");
    std::fs::write(out.join("frame-hashes.rs"), format!("{hashes:?}"))
        .expect("write fixed fingerprints");
    for path in ["src/command_list.rs", "permissions", "capabilities"] {
        println!("cargo::rerun-if-changed={path}");
    }
    check_grants();
    tauri_build::try_build(
        tauri_build::Attributes::new()
            .app_manifest(tauri_build::AppManifest::new().commands(COMMANDS)),
    )
    .expect("tauri-build 失败");
}
